<?php
declare(strict_types=1);
require_once __DIR__ . '/app/config/Conexion.php';require_once __DIR__ . '/app/helpers/funciones.php';require_once __DIR__ . '/app/dao/BebidaDAO.php';require_once __DIR__ . '/app/dao/PedidoDAO.php';
$db=Conexion::obtener();$mensaje='';$error='';$hayAdmin=(int)$db->query('SELECT COUNT(*) FROM administradores')->fetchColumn()>0;
if($_SERVER['REQUEST_METHOD']==='POST'){
    validar_csrf();$accion=$_POST['accion']??'';
    try{
        if($accion==='crear_admin'&&!$hayAdmin){$usuario=trim($_POST['usuario']??'');$pass=$_POST['password']??'';if(mb_strlen($usuario)<3||mb_strlen($pass)<10)throw new RuntimeException('Usá un nombre de usuario de 3 caracteres y una contraseña de al menos 10.');$st=$db->prepare('INSERT INTO administradores(usuario,password_hash) VALUES(?,?)');$st->execute([$usuario,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['admin_id']=(int)$db->lastInsertId();$_SESSION['admin_nombre']=$usuario;header('Location: admin.php');exit;}
        if($accion==='login'){$st=$db->prepare('SELECT * FROM administradores WHERE usuario=?');$st->execute([trim($_POST['usuario']??'')]);$admin=$st->fetch();if(!$admin||!password_verify($_POST['password']??'',$admin['password_hash']))throw new RuntimeException('Usuario o contraseña incorrectos.');session_regenerate_id(true);$_SESSION['admin_id']=(int)$admin['id'];$_SESSION['admin_nombre']=$admin['usuario'];header('Location: admin.php');exit;}
        requerir_admin();$bebidasDao=new BebidaDAO($db);$pedidoDao=new PedidoDAO($db);
        if($accion==='guardar_bebida'){$id=(int)($_POST['id']??0);$nombre=trim($_POST['nombre']??'');$precio=(float)($_POST['precio']??0);$stock=(int)($_POST['stock']??0);if(mb_strlen($nombre)<2||$precio<=0||$stock<0)throw new RuntimeException('Revisá el nombre, el precio y el stock.');$datos=[$nombre,trim($_POST['bodega']??''),trim($_POST['variedad']??'Tinto'),trim($_POST['region']??''),(int)($_POST['anio']??date('Y')),$precio,$stock,trim($_POST['imagen']??''),trim($_POST['descripcion']??''),(int)isset($_POST['activa']),(int)isset($_POST['destacada'])];$bebidasDao->guardar($datos,$id?:null);$mensaje=$id?'Bebida actualizada.':'Bebida agregada a la tienda.';}
        if($accion==='estado_bebida'){$bebidasDao->cambiarEstado((int)$_POST['id'],(int)$_POST['activo']);$mensaje='Disponibilidad actualizada.';}
        if($accion==='estado_pedido'){$pedidoDao->actualizarEstado((int)$_POST['id'],$_POST['estado']);$mensaje='Estado del pedido actualizado.';}
    }catch(Throwable $ex){$error=$ex instanceof RuntimeException?$ex->getMessage():'No pudimos completar la acción. Revisá la base de datos.';}
}
if(isset($_GET['salir'])){session_destroy();header('Location: admin.php');exit;}
$logged=es_admin();$bebidas=$logged?(new BebidaDAO($db))->listarTodas():[];$pedidos=$logged?(new PedidoDAO($db))->listar():[];$editar=null;
if($logged&&isset($_GET['editar'])){foreach($bebidas as $item)if((int)$item['id']===(int)$_GET['editar'])$editar=$item;}
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Administración · La Bodeguita de Munro</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="css/estilos.css"><link rel="stylesheet" href="css/admin.css"></head><body class="admin-body">
<header class="admin-top"><a href="index.php" class="wordmark"><span>La Bodeguita <small>de Munro</small></span></a><span>GESTIÓN DE LA TIENDA</span><?php if($logged): ?><a href="?salir=1">Cerrar sesión · <?= e($_SESSION['admin_nombre']??'') ?></a><?php else: ?><a href="index.php">Volver a la tienda ↗</a><?php endif; ?></header>
<main class="admin-main">
<?php if($error): ?><div class="admin-alert error" role="alert"><?= e($error) ?></div><?php elseif($mensaje): ?><div class="admin-alert" role="status"><?= e($mensaje) ?></div><?php endif; ?>
<?php if(!$logged): ?><section class="login-card"><p class="eyebrow">ESPACIO DE LA TIENDA</p><h1><?= $hayAdmin?'Qué bueno verte.':'Creá el acceso administrador.' ?></h1><p><?= $hayAdmin?'Ingresá con tu usuario para actualizar etiquetas, revisar pedidos y organizar el catálogo.':'Este primer paso crea el acceso privado de administración. Guardá bien la contraseña elegida.' ?></p><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="accion" value="<?= $hayAdmin?'login':'crear_admin' ?>"><label>Usuario<input name="usuario" required minlength="3" autocomplete="username"></label><label>Contraseña<input name="password" type="password" required <?= $hayAdmin?'':'minlength="10"' ?> autocomplete="<?= $hayAdmin?'current-password':'new-password' ?>"></label><button class="button button-dark" type="submit"><?= $hayAdmin?'Ingresar':'Crear acceso' ?> ↗</button></form><p class="login-foot">Tu catálogo se guarda en la base local de la tienda.</p></section>
<?php else: ?><div class="admin-heading"><div><p class="eyebrow">HOLA, <?= e(mb_strtoupper($_SESSION['admin_nombre']??'')) ?></p><h1>La tienda, <em>al día.</em></h1></div><a class="button button-outline" href="index.php" target="_blank">Ver tienda ↗</a></div><div class="admin-stats"><div><span>ETIQUETAS</span><strong><?= count($bebidas) ?></strong></div><div><span>PEDIDOS</span><strong><?= count($pedidos) ?></strong></div><div><span>POR PREPARAR</span><strong><?= count(array_filter($pedidos,fn($p)=>$p['estado']==='Pendiente')) ?></strong></div></div>
<section class="admin-section" id="bebidas"><div class="admin-section-heading"><div><p class="eyebrow">EL CATÁLOGO</p><h2><?= $editar?'Editar etiqueta':'Sumar una bebida' ?></h2></div><?php if($editar): ?><a class="text-link" href="admin.php#bebidas">Cancelar edición ×</a><?php endif; ?></div><form method="post" class="drink-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="accion" value="guardar_bebida"><input type="hidden" name="id" value="<?= (int)($editar['id']??0) ?>"><label>Nombre de la etiqueta<input name="nombre" required value="<?= e($editar['nombre']??'') ?>" placeholder="Ej. Malbec de la casa"></label><label>Bodega<input name="bodega" value="<?= e($editar['bodega']??'') ?>" placeholder="Nombre de la bodega"></label><label>Tipo<select name="variedad"><?php foreach(['Tinto','Blanco','Rosado','Espumante','Otro'] as $v): ?><option <?= ($editar['variedad']??'Tinto')===$v?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select></label><label>Región<input name="region" value="<?= e($editar['region']??'') ?>" placeholder="Ej. Valle de Uco, Mendoza"></label><label>Año<input type="number" name="anio" min="1900" max="2100" value="<?= e((string)($editar['anio']??date('Y'))) ?>"></label><label>Precio (ARS)<input type="number" name="precio" min="1" step="1" required value="<?= e((string)($editar['precio']??'')) ?>" placeholder="12000"></label><label>Unidades disponibles<input type="number" name="stock" min="0" required value="<?= e((string)($editar['stock']??0)) ?>"></label><label class="wide">Foto del producto (URL)<input type="url" name="imagen" value="<?= e($editar['imagen']??'') ?>" placeholder="https://…"><small>Dejalo vacío para mostrar la ilustración de botella.</small></label><label class="wide">Descripción breve<textarea name="descripcion" rows="2" placeholder="Notas, maridaje o recomendación de la casa"><?= e($editar['descripcion']??'') ?></textarea></label><div class="check-row"><label><input type="checkbox" name="activa" <?= !isset($editar)||$editar['activa']?'checked':'' ?>> Visible en la tienda</label><label><input type="checkbox" name="destacada" <?= !empty($editar['destacada'])?'checked':'' ?>> Recomendada por la casa</label></div><button class="button button-dark" type="submit"><?= $editar?'Guardar cambios':'Agregar al catálogo' ?> ↗</button></form>
<div class="table-wrap"><table><thead><tr><th>ETIQUETA</th><th>TIPO</th><th>PRECIO</th><th>STOCK</th><th>VISIBILIDAD</th><th></th></tr></thead><tbody><?php foreach($bebidas as $b): ?><tr><td><strong><?= e($b['nombre']) ?></strong><small><?= e($b['bodega']) ?></small></td><td><?= e($b['variedad']) ?></td><td><?= pesos((float)$b['precio']) ?></td><td><?= (int)$b['stock'] ?></td><td><span class="pill <?= $b['activa']?'':'off' ?>"><?= $b['activa']?'Visible':'Oculta' ?></span></td><td class="row-actions"><a href="?editar=<?= (int)$b['id'] ?>#bebidas">Editar</a><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="accion" value="estado_bebida"><input type="hidden" name="id" value="<?= (int)$b['id'] ?>"><input type="hidden" name="activo" value="<?= $b['activa']?0:1 ?>"><button><?= $b['activa']?'Ocultar':'Publicar' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="admin-section"><div class="admin-section-heading"><div><p class="eyebrow">VENTAS</p><h2>Pedidos recibidos</h2></div><p class="admin-hint">Los pedidos quedan pendientes hasta confirmar stock y pago con el cliente.</p></div><div class="orders-list"><?php if(!$pedidos): ?><p class="no-orders">Todavía no llegaron pedidos. Cuando alguien complete el carrito, van a aparecer acá.</p><?php endif; ?><?php foreach($pedidos as $p): ?><article class="order-card"><div class="order-top"><div><span class="order-number">PEDIDO #<?= (int)$p['id'] ?></span><strong><?= e($p['cliente_nombre']) ?></strong><small><?= e($p['cliente_email']) ?> · <?= e($p['cliente_telefono']) ?></small></div><span class="pill <?= $p['estado']==='Pendiente'?'pending':'ready' ?>"><?= e($p['estado']) ?></span></div><ul><?php foreach($p['items'] as $it): ?><li><?= (int)$it['cantidad'] ?> × <?= e($it['nombre_bebida']) ?> <span><?= pesos((float)$it['precio_unitario']*(int)$it['cantidad']) ?></span></li><?php endforeach; ?></ul><div class="order-bottom"><span><?= e($p['modalidad']) ?><?= $p['domicilio']?' · '.e($p['domicilio']):'' ?></span><strong><?= pesos((float)$p['total']) ?></strong></div><?php if($p['nota']): ?><p class="order-note">“<?= e($p['nota']) ?>”</p><?php endif; ?><form method="post" class="order-status"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="accion" value="estado_pedido"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><label for="status-<?= (int)$p['id'] ?>">Actualizar estado</label><select id="status-<?= (int)$p['id'] ?>" name="estado"><?php foreach(['Pendiente','Confirmado','Preparando','Listo para retirar','En camino','Entregado','Cancelado'] as $estado): ?><option <?= $p['estado']===$estado?'selected':'' ?>><?= e($estado) ?></option><?php endforeach; ?></select><button class="button button-outline">Guardar</button></form></article><?php endforeach; ?></div></section>
<?php endif; ?></main><script>document.querySelectorAll('.drink-form input[name="imagen"]').forEach(x=>x.addEventListener('input',()=>{if(x.value&&!/^https?:\/\//i.test(x.value))x.setCustomValidity('Ingresá una dirección web http o https.');else x.setCustomValidity('')}));</script></body></html>
